public class OrderPayloadParser {

    public class PayloadException extends Exception {
        public PayloadException(String message) {
            super(message);
        }
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public static Order parse(String body) {
        if (body == null || body.isBlank()) {
            throw new PayloadException('Body is null or blank');
        }

        Object root;
        try {
            root = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new PayloadException('Invalid JSON');
        }

        if (!(root instanceof Map<String, Object>)) {
            throw new PayloadException('JSON root is not an object');
        }

        Map<String, Object> obj = (Map<String, Object>) root;

        String orderNumber = asString(obj.get('number'));
        if (orderNumber == null || orderNumber.isBlank()) {
            throw new PayloadException('Missing or blank number');
        }

        Order order = new Order();
        order.orderNumber = orderNumber;

        Object dateVal = obj.get('date');
        if (dateVal != null) {
            String dateStr = asString(dateVal);
            if (dateStr != null && !dateStr.isBlank()) {
                try {
                    order.orderDate = Date.valueOf(dateStr);
                } catch (Exception e) {
                    throw new PayloadException('Invalid date');
                }
            }
        }

        order.currencyCode = asString(obj.get('currency'));

        Object customerVal = obj.get('customer');
        if (customerVal instanceof Map<String, Object>) {
            Map<String, Object> customer = (Map<String, Object>) customerVal;
            order.customerEmail = asString(customer.get('email'));
        }

        order.lines = new List<Line>();
        order.total = 0;

        Object linesVal = obj.get('lines');
        if (linesVal != null) {
            if (!(linesVal instanceof List<Object>)) {
                throw new PayloadException('lines is not an array');
            }
            List<Object> linesArr = (List<Object>) linesVal;
            for (Object lineObj : linesArr) {
                if (!(lineObj instanceof Map<String, Object>)) {
                    throw new PayloadException('Line is not an object');
                }
                Map<String, Object> lineMap = (Map<String, Object>) lineObj;

                Line line = new Line();

                String sku = asString(lineMap.get('sku'));
                if (sku == null || sku.isBlank()) {
                    throw new PayloadException('Line missing sku');
                }
                line.sku = sku;

                Integer quantity = asPositiveInteger(lineMap.get('quantity'));
                if (quantity == null) {
                    throw new PayloadException('Line missing or non-positive quantity');
                }
                line.quantity = quantity;

                Decimal unitPrice = asNonNegativeDecimal(lineMap.get('unitPrice'));
                if (unitPrice == null) {
                    throw new PayloadException('Line missing or negative unitPrice');
                }
                line.unitPrice = unitPrice;

                Decimal discount = asDecimal(lineMap.get('discount'));
                if (discount == null) {
                    discount = 0;
                }
                line.discount = discount;

                Decimal lineTotal = (line.quantity * line.unitPrice * (1 - line.discount))
                    .setScale(2, RoundingMode.HALF_UP);
                line.lineTotal = lineTotal;
                order.total += lineTotal;

                order.lines.add(line);
            }
        }

        return order;
    }

    public static String toAcknowledgement(Order order) {
        JSONGenerator gen = JSON.createGenerator();
        gen.writeStartObject();
        gen.writeStringField('number', order.orderNumber);
        gen.writeStringField('status', 'RECEIVED');
        Integer lineCount = order.lines != null ? order.lines.size() : 0;
        gen.writeNumberField('lineCount', lineCount);
        Decimal total = order.total != null ? order.total : 0;
        gen.writeNumberField('total', total);
        gen.writeEndObject();
        return gen.getAsString();
    }

    private static String asString(Object value) {
        if (value == null) {
            return null;
        }
        if (value instanceof String) {
            return (String) value;
        }
        return String.valueOf(value);
    }

    private static Decimal asDecimal(Object value) {
        if (value == null) {
            return null;
        }
        if (value instanceof Decimal) {
            return (Decimal) value;
        }
        if (value instanceof Integer) {
            return Decimal.valueOf((Long) (Integer) value);
        }
        if (value instanceof Long) {
            return Decimal.valueOf((Long) value);
        }
        if (value instanceof Double) {
            return Decimal.valueOf((Double) value);
        }
        return null;
    }

    private static Integer asPositiveInteger(Object value) {
        Decimal d = asDecimal(value);
        if (d == null) {
            return null;
        }
        Decimal floored = d.setScale(0, RoundingMode.FLOOR);
        if (d != floored) {
            return null;
        }
        if (d <= 0) {
            return null;
        }
        if (d > Integer.MAX_VALUE) {
            return null;
        }
        return floored.intValue();
    }

    private static Decimal asNonNegativeDecimal(Object value) {
        Decimal d = asDecimal(value);
        if (d == null) {
            return null;
        }
        if (d < 0) {
            return null;
        }
        return d;
    }
}
