public class Opportunities extends fflib_SObjectDomain
{
    public Opportunities(List<SObject> sObjectList)
    {
        super(sObjectList);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable
    {
        public fflib_SObjectDomain construct(List<SObject> sObjectList)
        {
            return new Opportunities(sObjectList);
        }
    }

    public override void onValidate()
    {
        for (SObject record : Records)
        {
            Opportunity opportunity = (Opportunity) record;

            if (opportunity.Amount != null && opportunity.Amount < 0)
            {
                error(
                    'Amount cannot be negative.',
                    opportunity,
                    Opportunity.Amount
                );
            }
        }
    }

    public override void onValidate(Map<Id, SObject> existingRecords)
    {
        if (existingRecords == null)
        {
            return;
        }

        for (SObject record : Records)
        {
            Opportunity opportunity = (Opportunity) record;
            Opportunity oldOpportunity = (Opportunity) existingRecords.get(opportunity.Id);

            if (oldOpportunity == null)
            {
                continue;
            }

            if (oldOpportunity.StageName == 'Closed Won' &&
                opportunity.Amount != oldOpportunity.Amount)
            {
                error(
                    'Amount cannot change on a won opportunity.',
                    opportunity,
                    Opportunity.Amount
                );
            }
        }
    }
}
