            || opp.Amount != Trigger.oldMap.get(opp.Id).Amount;

        if (recalculate) {
            accountIds.add(opp.AccountId);
        }
    }

    if (!accountIds.isEmpty()) {
        // One future call per transaction, carrying every affected account.
        // (One call per opportunity would exceed the 50 @future invocations
        // allowed per Apex transaction on a 200-record batch - see notes.)
        AccountRatingService.recalculate(accountIds);
    }
