trigger CaseTrigger on Case (after update) {
    if (!Trigger.isAfter || !Trigger.isUpdate) {
        return;
    }

    List<Case> newlyClosedCases = new List<Case>();

    for (Case c : Trigger.new) {
        Case oldCase = Trigger.oldMap.get(c.Id);

        // Only cases that transition from open to closed, with a contact, need a survey.
        if (oldCase != null && !oldCase.IsClosed && c.IsClosed && c.ContactId != null) {
            newlyClosedCases.add(c);
        }
    }

    if (newlyClosedCases.isEmpty()) {
        return;
    }

    // Common path: one Queueable job per case keeps failures isolated.
    // Salesforce limits System.enqueueJob to 50 calls per transaction, so larger
    // batches are fanned out through chained Queueable executions.
    if (newlyClosedCases.size() <= CaseSurveyJob.MAX_ENQUEUE_JOBS_PER_TRANSACTION) {
        for (Case c : newlyClosedCases) {
            System.enqueueJob(new CaseSurveyJob(c.Id));
        }
        return;
    }

    List<Id> caseIds = new List<Id>();
    for (Case c : newlyClosedCases) {
        caseIds.add(c.Id);
    }

    System.enqueueJob(new CaseSurveyJob(caseIds));
}
