import { LightningElement, api, track } from 'lwc';

let uidCounter = 0;

export default class StatusListbox extends LightningElement {
  @api label = '';

  @track _options = [];
  @track _value = '';
  @track _activeValue;
  _uid = 0;

  @api
  get options() {
    return this._options;
  }
  set options(value) {
    this._options = Array.isArray(value) ? value : [];
    this._activeValue = this._resolveActiveValue();
  }

  @api
  get value() {
    return this._value;
  }
  set value(val) {
    this._value = val;
    this._activeValue = this._resolveActiveValue();
  }

  connectedCallback() {
    this._uid = ++uidCounter;
    this._activeValue = this._resolveActiveValue();
  }

  get items() {
    const activeIndex = this._activeIndex;
    return this._options.map((option, index) => ({
      value: option.value,
      label: option.label,
      id: `${this._uid}-option-${index}`,
      selected: option.value === this._value ? 'true' : 'false',
      isActive: index === activeIndex
    }));
  }

  get activeDescendantId() {
    if (!this._options.length) {
      return null;
    }
    return `${this._uid}-option-${this._activeIndex}`;
  }

  get _activeIndex() {
    const index = this._options.findIndex((option) => option.value === this._activeValue);
    return index >= 0 ? index : 0;
  }

  _resolveActiveValue() {
    if (this._options.some((option) => option.value === this._value)) {
      return this._value;
    }
    return this._options.length ? this._options[0].value : undefined;
  }

  handleKeyDown = (event) => {
    const count = this._options.length;
    if (!count) {
      return;
    }

    const current = this._activeIndex;
    let next = current;
    let handled = true;

    switch (event.key) {
      case 'ArrowDown':
        next = Math.min(current + 1, count - 1);
        break;
      case 'ArrowUp':
        next = Math.max(current - 1, 0);
        break;
      case 'Home':
        next = 0;
        break;
      case 'End':
        next = count - 1;
        break;
      case 'Enter':
      case ' ':
        this._select(this._options[current].value);
        break;
      default:
        handled = false;
    }

    if (handled) {
      event.preventDefault();
      if (next !== current) {
        this._activeValue = this._options[next].value;
      }
    }
  };

  handleOptionClick = (event) => {
    const raw = event.currentTarget.dataset.value;
    const option = this._options.find((o) => String(o.value) === raw);
    if (!option) {
      return;
    }
    this._activeValue = option.value;
    this._select(option.value);
  };

  _select(value) {
    if (value === this._value) {
      return;
    }
    this._value = value;
    this._activeValue = value;
    this.dispatchEvent(new CustomEvent('change', { detail: { value } }));
  }
}
