public inherited sharing class EmployerService {
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        Set<Id> contactIds = new Set<Id>();
        for (Map.Entry<Id, Id> entry : employerByContactId.entrySet()) {
            if (entry.getKey() != null && entry.getValue() != null) {
                contactIds.add(entry.getKey());
            }
        }

        if (contactIds.isEmpty()) {
            return;
        }

        Map<Id, Set<Id>> primaryOrganizationIdsByContactId = new Map<Id, Set<Id>>();
        for (npe5__Affiliation__c affiliation : [
            SELECT Id, npe5__Contact__c, npe5__Organization__c
            FROM npe5__Affiliation__c
            WHERE npe5__Contact__c IN :contactIds
                AND npe5__Primary__c = true
        ]) {
            if (!primaryOrganizationIdsByContactId.containsKey(affiliation.npe5__Contact__c)) {
                primaryOrganizationIdsByContactId.put(
                    affiliation.npe5__Contact__c,
                    new Set<Id>()
                );
            }
            primaryOrganizationIdsByContactId.get(affiliation.npe5__Contact__c)
                .add(affiliation.npe5__Organization__c);
        }

        List<npe5__Affiliation__c> affiliationsToInsert = new List<npe5__Affiliation__c>();
        List<Contact> contactsToUpdate = new List<Contact>();

        for (Map.Entry<Id, Id> entry : employerByContactId.entrySet()) {
            Id contactId = entry.getKey();
            Id organizationId = entry.getValue();

            if (contactId == null || organizationId == null) {
                continue;
            }

            Set<Id> primaryOrganizationIds = primaryOrganizationIdsByContactId.get(contactId);
            if (primaryOrganizationIds != null && primaryOrganizationIds.contains(organizationId)) {
                continue;
            }

            affiliationsToInsert.add(new npe5__Affiliation__c(
                npe5__Contact__c = contactId,
                npe5__Organization__c = organizationId,
                npe5__Status__c = 'Current',
                npe5__Primary__c = true,
                npe5__StartDate__c = Date.today()
            ));

            contactsToUpdate.add(new Contact(
                Id = contactId,
                npsp__Primary_Affiliation__c = organizationId
            ));
        }

        if (!affiliationsToInsert.isEmpty()) {
            insert affiliationsToInsert;
        }

        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }
}
