public class GauAllocationService {
    public class AllocationException extends Exception {}

    public static List<npsp__Allocation__c> allocateByPercent(Id opportunityId, Map<Id, Decimal> percentByGauId) {
        if (opportunityId == null) {
            throw new AllocationException('Opportunity Id is required.');
        }
        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('percentByGauId must not be null or empty.');
        }

        Decimal totalPercent = 0;
        Set<Id> gauIds = new Set<Id>();

        for (Id gauId : percentByGauId.keySet()) {
            if (gauId == null) {
                throw new AllocationException('GAU Id must not be null.');
            }

            Decimal pct = percentByGauId.get(gauId);
            if (pct == null || pct <= 0) {
                throw new AllocationException('Each GAU percentage must be greater than 0.');
            }

            totalPercent += pct;
            gauIds.add(gauId);
        }

        if (totalPercent > 100) {
            throw new AllocationException('GAU percentages must not total more than 100%.');
        }

        List<Opportunity> opps = [
            SELECT Id, Amount
            FROM Opportunity
            WHERE Id = :opportunityId
            LIMIT 1
        ];
        if (opps.isEmpty()) {
            throw new AllocationException('Opportunity not found: ' + opportunityId);
        }

        Opportunity opp = opps[0];
        Decimal opportunityAmount = opp.Amount == null ? 0 : opp.Amount;

        Map<Id, npsp__General_Accounting_Unit__c> gausById = new Map<Id, npsp__General_Accounting_Unit__c>(
            [
                SELECT Id, npsp__Active__c
                FROM npsp__General_Accounting_Unit__c
                WHERE Id IN :gauIds
            ]
        );

        for (Id gauId : gauIds) {
            npsp__General_Accounting_Unit__c gau = gausById.get(gauId);
            if (gau == null) {
                throw new AllocationException('GAU not found: ' + gauId);
            }
            if (gau.npsp__Active__c != true) {
                throw new AllocationException('GAU is not active: ' + gauId);
            }
        }

        List<npsp__Allocation__c> existingAllocations = [
            SELECT Id
            FROM npsp__Allocation__c
            WHERE npsp__Opportunity__c = :opportunityId
        ];

        if (!existingAllocations.isEmpty()) {
            delete existingAllocations;
        }

        List<npsp__Allocation__c> newAllocations = new List<npsp__Allocation__c>();

        for (Id gauId : percentByGauId.keySet()) {
            Decimal pct = percentByGauId.get(gauId);

            npsp__Allocation__c allocation = new npsp__Allocation__c();
            allocation.npsp__Opportunity__c = opportunityId;
            allocation.npsp__General_Accounting_Unit__c = gauId;
            allocation.npsp__Percent__c = pct;
            allocation.npsp__Amount__c = (opportunityAmount * pct / 100).setScale(2, RoundingMode.HALF_UP);

            newAllocations.add(allocation);
        }

        insert newAllocations;

        return newAllocations;
    }
}
