public with sharing class RecordAccessService {
    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> editable = new Set<Id>();
        if (recordIds == null || recordIds.isEmpty()) {
            return editable;
        }

        // SOQL IN clause is limited to 1,000 values; chunk accordingly.
        final Integer BATCH_SIZE = 1000;
        List<Id> idList = new List<Id>(recordIds);

        for (Integer i = 0; i < idList.size(); i += BATCH_SIZE) {
            Integer endIdx = Math.min(i + BATCH_SIZE, idList.size());
            List<Id> batch = new List<Id>();
            for (Integer j = i; j < endIdx; j++) {
                batch.add(idList[j]);
            }

            for (UserRecordAccess access : [
                SELECT RecordId
                FROM UserRecordAccess
                WHERE RecordId IN :batch
                  AND UserId = :UserInfo.getUserId()
                  AND HasEditAccess = true
            ]) {
                editable.add(access.RecordId);
            }
        }

        return editable;
    }
}
