public inherited sharing class TA_Opportunity_CollectForErpSync
    implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate {

    private static final Set<Id> opportunityIdsToSync = new Set<Id>();

    public void afterInsert(List<SObject> triggerNew) {
        Set<Id> ids = new Set<Id>();

        for (SObject record : triggerNew) {
            Opportunity opportunity = (Opportunity) record;
            if (opportunity.Id != null) {
                ids.add(opportunity.Id);
            }
        }

        addOpportunityIdsForErpSync(ids);
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Map<Id, Opportunity> oldOpportunitiesById = new Map<Id, Opportunity>();

        for (SObject record : triggerOld) {
            Opportunity oldOpportunity = (Opportunity) record;
            oldOpportunitiesById.put(oldOpportunity.Id, oldOpportunity);
        }

        Set<Id> ids = new Set<Id>();

        for (SObject record : triggerNew) {
            Opportunity opportunity = (Opportunity) record;
            Opportunity oldOpportunity = oldOpportunitiesById.get(opportunity.Id);

            if (oldOpportunity != null && opportunity.StageName != oldOpportunity.StageName) {
                ids.add(opportunity.Id);
            }
        }

        addOpportunityIdsForErpSync(ids);
    }

    public static void addOpportunityIdsForErpSync(Set<Id> ids) {
        if (ids != null && !ids.isEmpty()) {
            opportunityIdsToSync.addAll(ids);
        }
    }

    public static Set<Id> getAndClearOpportunityIdsForErpSync() {
        Set<Id> ids = new Set<Id>(opportunityIdsToSync);
        opportunityIdsToSync.clear();
        return ids;
    }
}
