File: force-app/main/default/classes/TA_Contact_PreventDuplicateEmail.cls
```apex
/**
 * Trigger Actions Framework (TAF) action for Contact.
 *
 * Rule: two Contacts on the same Account may not share an Email address
 * (compared case-insensitively). Contacts without an Account or without an
 * Email are not checked.
 *
 * Registered for the before insert and before update contexts via
 * Trigger_Action__mdt records on the Contact sObject_Trigger_Setting__mdt.
 *
 * "without sharing" is intentional: a uniqueness/integrity check must be able
 * to see every existing Contact regardless of the running user's record access.
 * The query reads only Id/AccountId/Email to compare values; no data is exposed.
 */
public without sharing class TA_Contact_PreventDuplicateEmail
        implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    private static final String DUPLICATE_EMAIL_ERROR =
            'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        validateNoDuplicateEmail((List<Contact>) triggerNew);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        List<Contact> newContacts = (List<Contact>) triggerNew;
        List<Contact> oldContacts = (List<Contact>) triggerOld;

        // Only check contacts whose Email or AccountId changed, so existing
        // (legacy) duplicates do not block unrelated edits.
        List<Contact> changedContacts = new List<Contact>();
        Integer recordCount = newContacts == null ? 0 : newContacts.size();
        for (Integer i = 0; i < recordCount; i++) {
            Contact newContact = newContacts[i];
            Contact oldContact = oldContacts[i];
            if (newContact == null || oldContact == null) {
                continue;
            }
            if (newContact.Email != oldContact.Email
                    || newContact.AccountId != oldContact.AccountId) {
                changedContacts.add(newContact);
            }
        }

        validateNoDuplicateEmail(changedContacts);
    }

    private void validateNoDuplicateEmail(List<Contact> contacts) {
        if (contacts == null || contacts.isEmpty()) {
            return;
        }

        // Collect the contacts to check, preserving list order so that when
        // several contacts in one save share an account + email, the first one
        // in the list is accepted and each later one is rejected.
        List<Contact> candidates = new List<Contact>();
        Set<Id> accountIds = new Set<Id>();
        Set<String> emails = new Set<String>();
        Set<Id> candidateIds = new Set<Id>(); // a contact never conflicts with itself

        for (Contact contact : contacts) {
            if (contact == null) {
                continue;
            }
            // Contacts without an Account or without an Email are not checked.
            if (contact.AccountId == null || String.isBlank(contact.Email)) {
                continue;
            }
            candidates.add(contact);
            accountIds.add(contact.AccountId);
            emails.add(contact.Email); // SOQL string matching is case-insensitive
            if (contact.Id != null) {
                candidateIds.add(contact.Id);
            }
        }

        if (candidates.isEmpty()) {
            return;
        }

        // Exactly one SOQL query for the whole trigger execution (bulk-safe).
        // SOQL compares Email case-insensitively; keys below are lower-cased so
        // the in-memory comparison is case-insensitive as well.
        Set<String> existingKeys = new Set<String>();
        for (Contact existing : [
                SELECT Id, AccountId, Email
                FROM Contact
                WHERE AccountId IN :accountIds
                AND Email IN :emails
        ]) {
            if (candidateIds.contains(existing.Id)) {
                continue; // never conflict with self (relevant on update)
            }
            if (existing.AccountId == null || String.isBlank(existing.Email)) {
                continue;
            }
            existingKeys.add(key(existing.AccountId, existing.Email));
        }

        Set<String> claimedKeys = new Set<String>();
        for (Contact candidate : candidates) {
            String candidateKey = key(candidate.AccountId, candidate.Email);
            if (claimedKeys.contains(candidateKey)) {
                // A later contact in the same save duplicates an earlier one.
                candidate.addError(DUPLICATE_EMAIL_ERROR);
                continue;
            }
            claimedKeys.add(candidateKey);
            if (existingKeys.contains(candidateKey)) {
                candidate.addError(DUPLICATE_EMAIL_ERROR);
            }
        }
    }

    private static String key(Id accountId, String email) {
        return accountId + '|' + (email == null ? '' : email.toLowerCase());
    }
}
```

